import React from "react";

class Movie extends React.Component {
  constructor(props){
    super(props)
    this.state = {
      moviesArray: this.props.movieArray
    }
  }
  render() {
    return <div>
        <h1>Movies: </h1>
        <h1>Title: {<Route exact path="/" exact render={() => <Home />} />[0].title}</h1>
        <h1>Genre: {props.movies[0].genre}</h1>
        <h1>Rating: {props.movies[0].rated}</h1>
        <h1>Release Date: {props.movies[0].releaseDate}</h1>
        {console.log(this.state.moviesArray)}
        
      </div>
  }
}
export default Movie;
